@Test(description = "Unit test for selective cache refresh")
public void testSelectivePropertyRefreshInputs() {
    HelixDataAccessor accessor = mock(HelixDataAccessor.class);
    Map<String, HelixProperty> currentCache = ImmutableMap.of("instance0", new HelixProperty("key0"), "instance1", new HelixProperty("key1"));
    PropertyCache.PropertyCacheKeyFuncs<HelixProperty> mockCacheKeyFuncs = new PropertyCache.PropertyCacheKeyFuncs<HelixProperty>() {

        @Override
        public PropertyKey getRootKey(HelixDataAccessor accessor) {
            return mock(PropertyKey.class);
        }

        @Override
        public PropertyKey getObjPropertyKey(HelixDataAccessor accessor, String objName) {
            return new PropertyKey.Builder("fake").instance(objName);
        }

        @Override
        public String getObjName(HelixProperty obj) {
            return obj.getRecord().getId();
        }
    };
    when(accessor.getChildNames(any(PropertyKey.class))).thenReturn(ImmutableList.of("instance1", "instance2"));
    @SuppressWarnings("unchecked")
    PropertyCache<HelixProperty> propertyCache = new PropertyCache<>(MOCK_CONTROL_CONTEXT_PROVIDER, "mock property cache", mock(PropertyCache.PropertyCacheKeyFuncs.class), false);
    PropertyCache.SelectivePropertyRefreshInputs<HelixProperty> selectivePropertyRefreshInputs = propertyCache.genSelectiveUpdateInput(accessor, currentCache, mockCacheKeyFuncs);
    Assert.assertEquals(selectivePropertyRefreshInputs.getReloadKeys().size(), 1);
    Assert.assertEquals(selectivePropertyRefreshInputs.getReloadKeys().get(0), new PropertyKey.Builder("fake").instance("instance2"));
}

